codeExamples.code:
-- Delete ONE row (scoped by primary key)
DELETE FROM orders
WHERE order_id = 101;

-- Delete a set of rows matching a predicate
DELETE FROM orders
WHERE status = 'cancelled' AND order_date < '2025-01-01';

-- DANGER: no WHERE clause deletes EVERY row in the table!
-- DELETE FROM orders;   -- removes ALL orders

-- Safe pattern: preview the scope first
SELECT count(*) FROM orders WHERE status = 'cancelled' AND order_date < '2025-01-01';

-- Foreign key with cascade: deleting a customer removes their orders
CREATE TABLE orders (
    order_id   INT PRIMARY KEY,
    customer_id INT REFERENCES customers(customer_id) ON DELETE CASCADE
);

-- Transactional delete you can undo before COMMIT
BEGIN;
DELETE FROM customers WHERE customer_id = 7;  -- also cascades to orders
-- inspect affected counts; if wrong:
--   ROLLBACK;   -- restores customer AND cascaded orders
COMMIT;

-- Soft delete: mark as deleted instead of removing
UPDATE orders
SET deleted_at = now()
WHERE order_id = 101;

-- Application queries always filter out soft-deleted rows
SELECT * FROM orders WHERE deleted_at IS NULL;
